import{_ as a,o as i,c as t,a5 as r}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Media workspace UX","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/media-workspace-ux/spec.md","filePath":"feature/agency-workspace/media-workspace-ux/spec.md"}'),s={name:"feature/agency-workspace/media-workspace-ux/spec.md"};function o(n,e,c,l,d,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<p>&gt; Checkpoint 2026-10-17: restored specification and historical verification for retained Media Package/Campaign UI. Task UI changes described as rolled back remain out of this UX scope. API/classification changes after this checkpoint are governed by the Media Package package-simplification spec; historical fixture test results are not a new verification run.</p><h1 id="media-workspace-ux" tabindex="-1">Media workspace UX <a class="header-anchor" href="#media-workspace-ux" aria-label="Permalink to &quot;Media workspace UX&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Give Media Package and Media Campaign users the full available page width for long content and forms. Follow the existing BrandHub design. Task screens and logic are explicitly outside this change.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Replace package detail, custom package creation, terms negotiation and campaign completion review modals with in-page work areas. No overlay, focus trap or viewport-height cap for these workflows.</li><li>Keep current APIs, request payloads, versions, role checks, validation, error feedback and save semantics. Preserve unsaved-change confirmation and tab-close warnings.</li><li>Catalog details occupy the catalog width; returning retains query, availability filter and visible item count. Give visible return/cancel controls and focus the newly opened work area. Restore trigger focus on return when possible.</li><li>Retain only short discard confirmations as dialogs in these modules. Campaign cancellation&#39;s existing inline confirmation remains unchanged.</li><li>Reuse existing Button/Input/theme tokens, typography and spacing. Light/dark themes and 375/768/1440px layouts work without page overflow.</li><li>Add <code>mediaPackage.ui.backToPackages</code> to both vi/en mediaPackage.json. Reuse existing translated titles and actions elsewhere.</li></ul><h2 id="ui-states-errors" tabindex="-1">UI states / errors <a class="header-anchor" href="#ui-states-errors" aria-label="Permalink to &quot;UI states / errors&quot;">​</a></h2><p>Keep forms mounted during save/reload; failed submissions retain drafts. Successful saves return to the overview. Version conflict keeps the entered proposal. Long deliverables and closure lists use normal page scrolling.</p><h2 id="scope-and-done" tabindex="-1">Scope and done <a class="header-anchor" href="#scope-and-done" aria-label="Permalink to &quot;Scope and done&quot;">​</a></h2><p>UI only, no Task source changes, backend/schema/dependency changes or design replacement. Validate changed-source lint, production bundle, existing relevant E2E selectors, and browser fixtures covering save/cancel/discard/failure and responsive/theme behavior. Record existing build blockers separately.</p>',10)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
